import{_ as o,o as t,c as n,a0 as a}from"./chunks/framework.D4fUSYzX.js";const g=JSON.parse('{"title":"ADR 0037: The Consultation close takes w and confirms on a live Agent","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0037-the-consultation-close-takes-w-and-confirms-on-a-live-agent.md","filePath":"adr/0037-the-consultation-close-takes-w-and-confirms-on-a-live-agent.md"}'),s={name:"adr/0037-the-consultation-close-takes-w-and-confirms-on-a-live-agent.md"};function i(c,e,r,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0037-the-consultation-close-takes-w-and-confirms-on-a-live-agent" tabindex="-1">ADR 0037: The Consultation close takes w and confirms on a live Agent <a class="header-anchor" href="#adr-0037-the-consultation-close-takes-w-and-confirms-on-a-live-agent" aria-label="Permalink to &quot;ADR 0037: The Consultation close takes w and confirms on a live Agent&quot;">​</a></h1><p>Status: accepted Date: 2026-09-19</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0019 moved the Consultation close onto key <code>z</code> when <code>x</code> became the section toggle. The key carried no meaning, and it diverged from the Ticket section, where ADR 0031 put the work-cycle close on <code>w</code> with a confirmation whenever it stops a live agent. <code>z</code> is the left-pinky corner of the home row with nothing on it, and the two sections naming their most destructive action on different keys made the Key guide state a fact the operator had to memorize per section.</p><p>The Consultation close already had the confirmation decision; ADR 0019 only gave it a key. A close on a <code>missing</code> or a <code>failed</code> Consultation runs directly, because those records hold no agent to stop. A close on an <code>opening</code>, a <code>working</code>, or an <code>awaiting-response</code> Consultation stops a live agent, so it confirms first.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The Consultation close takes <code>w</code>, the key the Ticket work-cycle close holds (ADR 0031).</strong> Both sections name the close on the same key, and the Key guide states it once from the shared control catalogue, so the Action bar and the guide cannot disagree. The key moves in the catalogue only; the dispatch stays in the Consultation routes.</p><p><strong>The close confirms exactly when it stops a live agent.</strong> On an <code>opening</code>, a <code>working</code>, or an <code>awaiting-response</code> Consultation, the shared confirmation panel opens. Its first line states who is alive, worded per state, and its body states what the close keeps: the worktree and the branch on a worktree Consultation, the checkout on a live-worktree Consultation. Confirming closes, cancelling leaves the state unchanged.</p><p><strong>A <code>missing</code> or a <code>failed</code> Consultation closes directly.</strong> The record holds no agent, so the close has nothing to confirm. A <code>closing</code> Consultation opens the existing recovery panel with its Retry and Force-close rows, and a <code>closed</code> one refuses on the Message line. The close panel is one panel kind and one shared panel element; the record&#39;s state selects the shape - the confirmation rows on a live record, the recovery rows while closing - and a record the close panel cannot draw lets the panel go, with the reason stated on the Message line.</p><p>The considered alternatives:</p><ul><li>Keep <code>z</code>. Rejected: the key carries no meaning, and the sections name their close on different keys for no gain.</li><li>Refuse the live close and require a Recovery first. Rejected: stopping a live agent is a normal operator decision, not a recovery, and the confirmation is the record that it was made.</li><li>Confirm on every close, including <code>missing</code> and <code>failed</code>. Rejected: a record with no agent has nothing the confirmation could state, so the dialog would ask for a fact the record denies.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>ADR 0019&#39;s consequence that the Consultation close takes <code>z</code> is superseded in part by this ADR. Its other decisions hold.</li><li>The Ticket close (ADR 0031) and the Consultation close share one key. The dispatch resolves it per section: the Ticket section closes the work cycle of the selected ticket, the Consultation section closes or confirms the close of the selected Consultation.</li><li>The Key guide and the Action bar state Close on <code>w</code> in both sections, from the shared catalogue.</li><li>The confirmation body&#39;s environment split keeps the surviving resources honest: a live-worktree close never states that a worktree stays, because it keeps the operator&#39;s own checkout.</li></ul>',13)])])}const p=o(s,[["render",i]]);export{g as __pageData,p as default};
